CREATE OR REPLACE FUNCTION public.add_ai_credits(p_shop_id uuid, p_amount integer, p_reason text DEFAULT 'topup'::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(success boolean, new_balance integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_balance INT;
BEGIN
  IF p_amount <= 0 THEN
    RETURN QUERY SELECT FALSE, 0;
    RETURN;
  END IF;

  UPDATE shops
     SET ai_credits = COALESCE(ai_credits, 0) + p_amount,
         updated_at = NOW()
   WHERE id = p_shop_id
   RETURNING ai_credits INTO v_balance;

  IF v_balance IS NULL THEN
    RETURN QUERY SELECT FALSE, 0;
    RETURN;
  END IF;

  INSERT INTO credit_transactions (shop_id, amount, balance_after, reason, metadata)
  VALUES (p_shop_id, p_amount, v_balance, p_reason, p_metadata);

  RETURN QUERY SELECT TRUE, v_balance;
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_omise_charge_once(p_shop_id uuid, p_plan_key text, p_charge_id text, p_amount numeric, p_currency text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_status TEXT;
  v_current TIMESTAMPTZ;
  v_expires TIMESTAMPTZ;
  v_claimed INT;
BEGIN
  IF p_shop_id IS NULL OR p_plan_key IS NULL OR p_charge_id IS NULL OR length(trim(p_charge_id)) = 0 THEN
    RETURN jsonb_build_object('applied', false, 'reason', 'invalid');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('omise:' || p_charge_id, 0));

  SELECT plan_expires_at INTO v_current
  FROM public.shops
  WHERE id = p_shop_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('applied', false, 'reason', 'shop_not_found');
  END IF;

  SELECT status INTO v_status
  FROM public.billing_payments
  WHERE provider = 'omise' AND provider_ref = p_charge_id
  FOR UPDATE;

  INSERT INTO public.billing_webhook_events (provider, event_id, shop_id)
  VALUES ('omise', p_charge_id, p_shop_id)
  ON CONFLICT (provider, event_id) DO NOTHING;

  GET DIAGNOSTICS v_claimed = ROW_COUNT;

  IF v_claimed = 0 OR v_status IN ('succeeded', 'verified') THEN
    RETURN jsonb_build_object(
      'applied', false,
      'reason', CASE WHEN v_status IN ('succeeded', 'verified') THEN 'already_succeeded' ELSE 'duplicate' END
    );
  END IF;

  IF v_current IS NOT NULL AND v_current > now() THEN
    v_expires := v_current + interval '1 month';
  ELSE
    v_expires := now() + interval '1 month';
  END IF;

  UPDATE public.shops
  SET plan_key = p_plan_key,
      plan = p_plan_key,
      package_name = p_plan_key,
      subscription_provider = 'omise',
      subscription_id = NULL,
      subscription_status = 'active',
      plan_expires_at = v_expires,
      updated_at = now()
  WHERE id = p_shop_id;

  INSERT INTO public.billing_payments (
    shop_id, provider, plan_key, amount, currency, status, provider_ref
  ) VALUES (
    p_shop_id,
    'omise',
    p_plan_key,
    COALESCE(p_amount, 0),
    COALESCE(NULLIF(p_currency, ''), 'THB'),
    'succeeded',
    p_charge_id
  )
  ON CONFLICT (provider, provider_ref)
  DO UPDATE SET
    status = 'succeeded',
    plan_key = EXCLUDED.plan_key;

  RETURN jsonb_build_object('applied', true, 'plan_expires_at', v_expires);
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_stripe_checkout_once(p_event_id text, p_shop_id uuid, p_plan_key text, p_amount numeric, p_currency text, p_session_id text, p_subscription_id text, p_customer_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_claimed INT;
BEGIN
  IF p_event_id IS NULL OR p_shop_id IS NULL OR p_plan_key IS NULL OR p_session_id IS NULL THEN
    RETURN jsonb_build_object('applied', false, 'reason', 'invalid');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('stripe:' || p_event_id, 0));

  PERFORM 1 FROM public.shops WHERE id = p_shop_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('applied', false, 'reason', 'shop_not_found');
  END IF;

  INSERT INTO public.billing_webhook_events (provider, event_id, shop_id)
  VALUES ('stripe', p_event_id, p_shop_id)
  ON CONFLICT (provider, event_id) DO NOTHING;

  GET DIAGNOSTICS v_claimed = ROW_COUNT;
  IF v_claimed = 0 THEN
    RETURN jsonb_build_object('applied', false, 'reason', 'duplicate');
  END IF;

  UPDATE public.shops
  SET plan_key = p_plan_key,
      plan = p_plan_key,
      subscription_provider = 'stripe',
      subscription_id = COALESCE(p_subscription_id, subscription_id),
      subscription_status = 'active',
      stripe_customer_id = COALESCE(p_customer_id, stripe_customer_id),
      updated_at = now()
  WHERE id = p_shop_id;

  INSERT INTO public.billing_payments (
    shop_id, provider, plan_key, amount, currency, status, provider_ref
  ) VALUES (
    p_shop_id,
    'stripe',
    p_plan_key,
    COALESCE(p_amount, 0),
    COALESCE(NULLIF(p_currency, ''), 'THB'),
    'succeeded',
    p_session_id
  )
  ON CONFLICT (provider, provider_ref) DO NOTHING;

  RETURN jsonb_build_object('applied', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_stripe_invoice_failed_once(p_event_id text, p_invoice_id text, p_subscription_id text, p_amount numeric, p_currency text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_shop_id UUID;
  v_claimed INT;
BEGIN
  IF p_event_id IS NULL OR p_invoice_id IS NULL THEN
    RETURN jsonb_build_object('applied', false, 'reason', 'invalid');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('stripe:' || p_event_id, 0));

  IF p_subscription_id IS NULL OR length(trim(p_subscription_id)) = 0 THEN
    RETURN jsonb_build_object('applied', false, 'reason', 'no_subscription');
  END IF;

  SELECT id INTO v_shop_id
  FROM public.shops
  WHERE subscription_id = p_subscription_id
  LIMIT 1;

  IF v_shop_id IS NULL THEN
    RETURN jsonb_build_object('applied', false, 'reason', 'shop_not_found');
  END IF;

  PERFORM 1 FROM public.shops WHERE id = v_shop_id FOR UPDATE;

  INSERT INTO public.billing_webhook_events (provider, event_id, shop_id)
  VALUES ('stripe', p_event_id, v_shop_id)
  ON CONFLICT (provider, event_id) DO NOTHING;

  GET DIAGNOSTICS v_claimed = ROW_COUNT;
  IF v_claimed = 0 THEN
    RETURN jsonb_build_object('applied', false, 'reason', 'duplicate');
  END IF;

  UPDATE public.shops
  SET subscription_status = 'past_due',
      updated_at = now()
  WHERE id = v_shop_id;

  INSERT INTO public.billing_payments (
    shop_id, provider, amount, currency, status, provider_ref
  ) VALUES (
    v_shop_id,
    'stripe',
    COALESCE(p_amount, 0),
    COALESCE(NULLIF(p_currency, ''), 'THB'),
    'failed',
    p_invoice_id
  )
  ON CONFLICT (provider, provider_ref) DO NOTHING;

  RETURN jsonb_build_object('applied', true, 'shop_id', v_shop_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_demo_message(p_visitor text, p_per_visitor integer, p_global integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_day date := (now() at time zone 'Asia/Bangkok')::date;
  v_global int;
  v_mine int;
begin
  -- Visitors are 'v:<cookie>'; the per-network guard rows ('ip:<address>') count the same
  -- messages a second time, so they stay out of the global total
  select coalesce(sum(messages), 0) into v_global
  from public.demo_usage where day = v_day and visitor_id not like 'ip:%';
  if v_global >= p_global then
    return 'global_limit';
  end if;

  insert into public.demo_usage (visitor_id, day, messages)
  values (p_visitor, v_day, 1)
  on conflict (visitor_id, day) do update
    set messages = public.demo_usage.messages + 1
    where public.demo_usage.messages < p_per_visitor
  returning messages into v_mine;

  if v_mine is null then
    return 'visitor_limit';
  end if;
  return 'ok';
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_slip_check(p_shop_id uuid, p_period text, p_limit integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_used INT;
  v_source TEXT;
BEGIN
  INSERT INTO public.usage_logs (shop_id, period) VALUES (p_shop_id, p_period)
  ON CONFLICT (shop_id, period) DO NOTHING;

  SELECT slips_used INTO v_used FROM public.usage_logs
  WHERE shop_id = p_shop_id AND period = p_period FOR UPDATE;

  IF p_limit < 0 OR v_used < p_limit THEN
    v_source := 'plan';
  ELSIF public.consume_addon_credit(p_shop_id, 'slips') THEN
    v_source := 'addon';
  ELSE
    RETURN 'none';
  END IF;

  UPDATE public.usage_logs
  SET slips_used = slips_used + 1, updated_at = now()
  WHERE shop_id = p_shop_id AND period = p_period;

  RETURN v_source;
END;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_demo_shops(p_hours integer DEFAULT 6)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_shops uuid[] := array[
    'd3300000-0000-4000-8000-000000000001'::uuid,
    'd3300000-0000-4000-8000-000000000002'::uuid,
    'd3300000-0000-4000-8000-000000000003'::uuid
  ];
  v_cutoff timestamptz := now() - make_interval(hours => p_hours);
  v_stale uuid[];
  v_table text;
  v_count int;
  v_total int := 0;
begin
  -- A conversation is stale once nobody has written in it for p_hours
  select coalesce(array_agg(id), '{}') into v_stale
  from public.conversations
  where shop_id = any(v_shops) and coalesce(last_message_at, created_at) < v_cutoff;

  -- Children first. Each delete runs in its own block: a table this install doesn't have,
  -- or a foreign key nobody expected, skips that one table instead of the whole cleanup.
  foreach v_table in array array[
    'chat_messages', 'payment_slips', 'follow_up_tasks', 'orders', 'bookings',
    'leads', 'customer_profiles', 'sales_trajectories'
  ] loop
    begin
      if to_regclass('public.' || v_table) is null then continue; end if;
      if exists (select 1 from information_schema.columns
                 where table_schema = 'public' and table_name = v_table and column_name = 'conversation_id') then
        execute format('delete from public.%I where conversation_id = any($1)', v_table) using v_stale;
        get diagnostics v_count = row_count;
        v_total := v_total + v_count;
      end if;
      if exists (select 1 from information_schema.columns
                 where table_schema = 'public' and table_name = v_table and column_name = 'shop_id')
         and exists (select 1 from information_schema.columns
                 where table_schema = 'public' and table_name = v_table and column_name = 'created_at') then
        execute format('delete from public.%I where shop_id = any($1) and created_at < $2', v_table)
          using v_shops, v_cutoff;
        get diagnostics v_count = row_count;
        v_total := v_total + v_count;
      end if;
    exception when others then
      raise warning '[cleanup_demo_shops] skipped %: %', v_table, sqlerrm;
    end;
  end loop;

  begin
    delete from public.conversations where id = any(v_stale);
    get diagnostics v_count = row_count;
    v_total := v_total + v_count;
  exception when others then
    raise warning '[cleanup_demo_shops] skipped conversations: %', sqlerrm;
  end;

  update public.products set stock = 50 where shop_id = any(v_shops) and stock < 50;
  delete from public.demo_usage where day < (now() at time zone 'Asia/Bangkok')::date - 7;

  return v_total;
end;
$function$

CREATE OR REPLACE FUNCTION public.deduct_ai_credits(p_shop_id uuid, p_amount integer DEFAULT 1, p_reason text DEFAULT 'ai_chat'::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(success boolean, new_balance integer, deducted integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_balance INT;
  v_byok    TEXT;
BEGIN
  -- Lock row เพื่อกัน race
  SELECT ai_credits, custom_ai_key
    INTO v_balance, v_byok
    FROM shops WHERE id = p_shop_id FOR UPDATE;

  -- BYOK = ใช้ key ตัวเอง ไม่หักเครดิตของระบบ
  IF v_byok IS NOT NULL AND v_byok != '' THEN
    RETURN QUERY SELECT TRUE, COALESCE(v_balance, 0), 0;
    RETURN;
  END IF;

  -- เครดิตไม่พอ
  IF v_balance IS NULL OR v_balance < p_amount THEN
    RETURN QUERY SELECT FALSE, COALESCE(v_balance, 0), 0;
    RETURN;
  END IF;

  -- หักเครดิต atomically
  UPDATE shops
     SET ai_credits = ai_credits - p_amount,
         updated_at = NOW()
   WHERE id = p_shop_id
   RETURNING ai_credits INTO v_balance;

  -- บันทึก transaction log
  INSERT INTO credit_transactions (shop_id, amount, balance_after, reason, metadata)
  VALUES (p_shop_id, -p_amount, v_balance, p_reason, p_metadata);

  RETURN QUERY SELECT TRUE, v_balance, p_amount;
END;
$function$

CREATE OR REPLACE FUNCTION public.gen_booking_code(p_shop_id uuid)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
  yr int := EXTRACT(YEAR FROM now());
  cnt int;
BEGIN
  SELECT COUNT(*) + 1 INTO cnt
  FROM public.bookings
  WHERE shop_id = p_shop_id
    AND EXTRACT(YEAR FROM created_at) = yr;
  RETURN 'BK-' || yr || '-' || LPAD(cnt::text, 4, '0');
END;
$function$

